import React from "react";

const colors = ["primary", "secondary", "accent", "neutral", "warning", "error", "success"];
const shades = ["50", "100", "200", "300", "400", "500", "600", "700", "800", "900"];

const Palette = () => {
  return (
    <div className="grid grid-cols-3 lg:grid-cols-7 gap-4 items-center">
      {colors.map((color) => (
        <div key={color} className="flex flex-col items-center w-full">
          {/* Color base con nombre */}
          <div
            className={`h-16 w-44 flex justify-center items-center border-2 rounded-full bg-${color} text-white font-semibold`}
          >
            {color}
          </div>

          {/* Tonos con valores */}
          <div className="grid grid-cols-5 gap-2">
            {shades.map((shade) => (
              <div
                key={`${color}-${shade}`}
                className={`h-6 w-8 flex justify-center items-center border rounded bg-${color}-${shade} text-xs text-black/70`}
              >
                {shade}
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
};

export default Palette;
