import * as React from "react";
import Layout from "../components/layout";
import { graphql, PageProps } from "gatsby";
import  data  from "../data/data.json";
import { UserProfile } from "../interfaces";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Palette from "../components/palette";
import EmailForm from "../components/emailForm";

const userData: UserProfile = data;

const SablagePlancherPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  return (
    <Layout data={userData}>
      <Palette />
      <section className={styles.container}>
        <h1>Sablage de plancher</h1>
      </section>
    </Layout>
  )
}

export default SablagePlancherPage


export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "flex flex-col w-full p-8 gap-8",
  section: "bg-primary/50 border-primary flex min-h-96 p-8 border rounded-lg shadow-lg shadow-neutral/50",
  title: "text-accent text-4xl ",
}